INSERT INTO translations (lang_key, lang_code, value, updated_at) VALUES ('Only QuantumClaw offers enterprise-grade quantum computing access alongside 400+ AI models. No other platform combines classical AI and quantum resources in a single API.', 'ar', 'QuantumClaw فقط هو الذي يوفر وصولاً كمياً مؤسسياً بالإضافة إلى أكثر من 400 نموذج ذكاء اصطناعي. لا توجد منصات أخرى تدمج موارد الذكاء الاصطناعي الكلاسيكية والكمومية في واجهة برمجة تطبيقات واحدة.', NOW());
